use std::fs

fn digit_val(c: char) -> int {
    let b = c as int
    if b >= 48 && b <= 57 {
        b - 48
    } else if b >= 65 && b <= 90 {
        b - 55
    } else if b >= 97 && b <= 122 {
        b - 87
    } else {
        0
    }
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let digits = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().collect()
        if parts.len() < 3 {
            continue
        }
        let from: int = parts[1].parse::<int>().unwrap_or(10)
        let to: int = parts[2].parse::<int>().unwrap_or(10)
        let mut n: int = 0
        for c in parts[0].chars() {
            n = n * from + digit_val(c)
        }
        if n == 0 {
            println("0")
            continue
        }
        let mut out: Vec<char> = []
        while n > 0 {
            let d = (n % to) as usize
            out.push(digits.chars().nth(d).unwrap_or('0'))
            n = n / to
        }
        let mut s = ""
        let mut i = out.len() as int - 1
        while i >= 0 {
            s = s + out[i as usize].to_string()
            i = i - 1
        }
        println("${s}")
    }
}

